144	 * only form every provider that accepts a seed can carry on its wire.
145	 * @param value - candidate seed.
146	 * @returns whether the value can be sent as a seed and written into a stamp.
147	 */
148	export function isSeed(value: unknown): value is number {
149	  return typeof value === 'number' && Number.isSafeInteger(value) && value >= 0
150	}
