152	/**
153	 * Decode a value that declares itself as an environment run stamp. Unrelated
154	 * values return `undefined`; a malformed stamp fails replay loudly, as every
155	 * durable payload does at the log boundary.
156	 * @param value - candidate durable payload.
157	 * @returns the validated stamp, or `undefined` for another value kind.
158	 */
159	export function decodeEnvironmentRun(value: unknown): EnvironmentRunStamp | undefined {
160	  if (!isRecord(value) || value['kind'] !== 'environment/run') return undefined
161	  if (value['version'] !== ENVIRONMENT_RUN_VERSION) {
162	    throw new Error(`unsupported environment/run version ${String(value['version'])}`)
163	  }
164	  const heldOut = value['heldOut']
165	  if (typeof heldOut !== 'boolean') throw new Error('environment/run heldOut must be a boolean')
166	  const repetition = value['repetition']
167	  if (typeof repetition !== 'number' || !Number.isSafeInteger(repetition) || repetition < 0) {
168	    throw new Error('environment/run repetition must be a non-negative integer')
169	  }
170	  const model = stampModel(value['model'], 'model')
171	  const ladder = value['ladder'] === undefined ? {} : { ladder: stampLadder(value['ladder']) }
172	  const isolation = value['isolation']
173	  if (typeof isolation !== 'string' || !ISOLATIONS.has(isolation)) {
174	    throw new Error('environment/run isolation must be none, process, or host')
175	  }
176	  const fixture = value['fixtureSha256'] === undefined ? {} : { fixtureSha256: stampHex(value, 'fixtureSha256') }
177	  const group = value['group'] === undefined ? {} : { group: stampText(value, 'group') }
178	  const district = value['district'] === undefined ? {} : { district: stampText(value, 'district') }
179	  const policyVersion = value['policyVersion'] === undefined ? {} : { policyVersion: stampText(value, 'policyVersion') }
180	  const seed = value['seed'] === undefined ? {} : { seed: stampSeed(value['seed']) }
181	  const implementer = value['implementer'] === undefined ? {} : { implementer: stampText(value, 'implementer') }
182	  return {
183	    kind: 'environment/run',
184	    version: ENVIRONMENT_RUN_VERSION,
185	    environmentId: EnvironmentId(stampText(value, 'environmentId')),
186	    environmentKind: stampText(value, 'environmentKind'),
187	    heldOut,
188	    promptSha256: stampHex(value, 'promptSha256'),
189	    checksSha256: stampHex(value, 'checksSha256'),
190	    ...fixture,
191	    contentSha256: stampHex(value, 'contentSha256'),
192	    repetition,
193	    ...group,
194	    ...district,
195	    ...policyVersion,
196	    ...seed,
197	    model,
198	    ...ladder,
199	    isolation: isolation as EnvironmentRunStamp['isolation'],
200	    ...implementer,
201	  }
202	}
