211	  }
212	  recordRun(
213	    _agent: Agent,
214	    ref: StandardRef,
215	    isolation: CertificateIsolation,
216	    results: readonly CheckResult[],
217	    evidence: RunEvidence,
218	  ): RunOutcome {
219	    this.runs.push({ ref, isolation, results, evidence })
220	    const failures = results.filter(result => result.status === 'fail')
221	    if (failures.length > 0) return { certified: false, failures }
222	    return {
223	      certified: true,
224	      certificate: {
225	        standard: ref,
226	        goalId: (this.view as StandardView).goalId,
227	        isolation,
228	        executor: evidence.executor,
229	        results: [...results],
230	        recordedAt: 5,
231	      },
232	    }
233	  }
234	  issueDirective(_agent: Agent, _ref: StandardRef, request: DirectiveRequest): void {
235	    this.directives.push(request)
236	  }
