326	/** What one scripted child run resolves with and leaves behind. */
327	interface ScriptedChild {
328	  readonly result?: SubagentResult
329	  /** Assistant usage of an in-process child's own session; absent publishes a remote run. */
330	  readonly childUsage?: { inputTokens: number; outputTokens: number }
331	  /** What the child did to the workspace before it settled. */
332	  readonly work?: (workspace: string) => void
333	  /** Settle only once the start signal aborts, as a provider whose child runs until cancelled does. */
334	  readonly untilAborted?: true
335	  /** Reject the start once the signal aborts, as a provider refusing to start an already-cancelled run does. */
336	  readonly failsToStart?: true
337	}
338	
339	/** A promise that settles when `signal` aborts, or at once when it already has. */
340	function whenAborted(signal: AbortSignal): Promise<void> {
341	  if (signal.aborted) return Promise.resolve()
342	  return new Promise((resolve) => {
343	    signal.addEventListener('abort', () => { resolve() }, { once: true })
344	  })
345	}
