347	/** The subagent seam as the runner reads it: a provider registry and one published run per start. */
348	class StubSubagents extends Service {
349	  static current: StubSubagents
350	  readonly providers = new Map<string, SubagentProvider>()
351	  readonly started: { name: string; request: SubagentStartRequest }[] = []
352	  disposed = 0
353	  workspace = ''
354	  /** One entry per start, in start order; a start past the end settles as a bare completion. */
355	  children: ScriptedChild[] = []
356	  constructor(ctx: Context) {
357	    super(ctx, 'subagents')
358	    StubSubagents.current = this
359	  }
360	
361	  register(name: string, capabilities: SubagentProvider['capabilities']): void {
362	    this.providers.set(name, { name, capabilities, inheritsParentContext: false, start: () => Promise.reject(new Error('unused')) })
363	  }
364	
365	  getProvider(name: string): SubagentProvider | undefined {
366	    return this.providers.get(name)
367	  }
368	
369	  async start(name: string, request: SubagentStartRequest): Promise<SubagentRun> {
370	    this.started.push({ name, request })
371	    const scripted = this.children[this.started.length - 1] ?? {}
372	    if (scripted.failsToStart === true) {
373	      await whenAborted(request.signal)
374	      throw new Error('stub-subagents: the run was cancelled before startup')
375	    }
376	    scripted.work?.(this.workspace)
377	    const child = new FakeAgent(`child-${this.started.length}`, () => {})
378	    if (scripted.childUsage !== undefined) {
379	      child.session.append('assistant/message', { turn: 1, step: 1, usage: scripted.childUsage, message: { content: [] } })
380	    }
381	    const settled: SubagentResult = scripted.result ?? { output: [], stopReason: 'completed' }
382	    return {
383	      id: SessionId(`child-${this.started.length}`),
384	      localAgent: scripted.childUsage === undefined ? undefined : asAgent(child),
385	      result: scripted.untilAborted === true
386	        ? whenAborted(request.signal).then(() => settled)
387	        : Promise.resolve(settled),
388	      dispose: async () => { this.disposed += 1 },
389	    }
390	  }
391	}
