422	interface Scenario {
423	  config?: Partial<Config>
424	  definition?: EnvironmentDefinition
425	  onTurn?: (turn: number, session: FakeSession) => void
426	  /** Mount the read barrier so the run reserves a directory; its prefix names the barrier root. */
427	  barrierPrefix?: string
428	  /** Mount the subagent seam and register these providers under their names. */
429	  providers?: Readonly<Record<string, SubagentProvider['capabilities']>>
430	  /** Caps the composed budget policy enforces; omitted composes it uncapped. */
431	  budget?: budgetPolicy.Config
