436	interface Harness {
437	  ctx: Context
438	  workspace: string
439	  barrierRoot: string | undefined
440	  run: (extra?: object) => Promise<EnvironmentRunReport>
441	}
442	
443	async function harness(scenario: Scenario = {}): Promise<Harness> {
444	  const ctx = new Context()
445	  for (const stub of [StubEnvironments, StubDefaultModel, StubAgents, StubGoals, StubStandards, StubShell, StubSessions]) {
446	    await ctx.plugin(stub)
447	  }
448	  let barrierRoot: string | undefined
449	  if (scenario.barrierPrefix !== undefined) {
450	    await ctx.plugin(StubReadBarrier)
451	    barrierRoot = await mkdtemp(join(tmpdir(), scenario.barrierPrefix))
452	    StubReadBarrier.current.root = barrierRoot
453	  }
454	  if (scenario.providers !== undefined) {
455	    await ctx.plugin(StubSubagents)
456	    for (const [name, capabilities] of Object.entries(scenario.providers)) StubSubagents.current.register(name, capabilities)
457	  }
458	  // Village rule: a composition running unattended cells carries a session
459	  // budget, and a delegated run is refused without one.
460	  if (scenario.unbudgeted !== true) await ctx.plugin(budgetPolicy, scenario.budget ?? {})
461	  await ctx.plugin(EnvironmentRunner, { isolation: 'process', ...scenario.config })
462	  const definition = scenario.definition ?? environment()
463	  StubEnvironments.current.definitions.set(definition.id, definition)
464	  StubAgents.current.agent = new FakeAgent('environment-test', scenario.onTurn ?? assistantTurns)
465	  const workspace = await mkdtemp(join(tmpdir(), 'environment-runner-'))
466	  if (scenario.providers !== undefined) StubSubagents.current.workspace = workspace
467	  const run = (extra: object = {}) => ctx.environmentRuns.run({ environment: definition.id, workspace, ...extra })
468	  return { ctx, workspace, barrierRoot, run }
469	}
