 * @throws {@link EnvironmentRunError} for an empty ladder and for one past the ceiling.
 */
export function resolveLadder(
  ladder: readonly EnvironmentRunRung[] | undefined,
  model: EnvironmentRunModel,
  maxRungs: number,
